//! 🧪️ Partial copied views and every settlement stage retain their exact original owners.
use super::*;
fn close(cursor:&mut EditMessageSettlement){cursor.begin_close();for _ in 0..1_000_000{if cursor.terminal_is_empty(){return;}let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_close_copy_byte_demand().unwrap(),maximum_capacity_bytes:cursor.next_close_capacity_byte_demand(4096).unwrap(),maximum_release_bytes:cursor.next_close_release_byte_demand().unwrap(),maximum_depth:cursor.next_close_depth_demand().unwrap()};let(step,allocated,released)=crate::test_allocation::observe_backing(||cursor.close_step(grant).unwrap());assert_eq!(allocated,0);assert!(step.progress().fits(grant));assert_eq!(released,step.progress().released_bytes);}panic!("settlement exact close did not terminate");}
#[test]
fn edit_message_clamp_partial_copy_retirement_exposes_exact_whole_release(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();for copy_bytes in law["settlement"]["copyRelease"]["copyGrants"].as_array().unwrap(){let source=MutationMessage::fatal("mutation.invariant","x".repeat(law["settlement"]["copyRelease"]["allocationBytes"].as_u64().unwrap()as usize));let mut copy=MessageCopyCursor::new();for _ in 0..12{let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy.next_copy_byte_demand(&source).unwrap().max(copy_bytes.as_u64().unwrap()as usize),maximum_capacity_bytes:copy.next_capacity_byte_demand(&source).unwrap(),maximum_release_bytes:0,maximum_depth:1};copy.advance(&source,grant).unwrap();}copy.cancel();copy.begin_close();let mut released=0;for _ in 0..1000{if copy.terminal_is_empty(){break;}let demand=copy.next_close_release_byte_demand().unwrap();assert!(demand<=law["settlement"]["maximumReleaseBytes"].as_u64().unwrap()as usize);let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy.next_close_copy_byte_demand().unwrap(),maximum_capacity_bytes:0,maximum_release_bytes:demand,maximum_depth:copy.next_close_depth_demand().unwrap()};if demand>0{let(step,allocated,freed)=crate::test_allocation::observe_backing(||copy.close_step(RetainedCloneGrant {maximum_release_bytes:demand-1,..grant}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((allocated,freed),(0,0));assert_eq!(copy.next_close_release_byte_demand().unwrap(),demand);}let(step,allocated,freed)=crate::test_allocation::observe_backing(||copy.close_step(grant).unwrap());assert_eq!(allocated,0);assert!(step.progress().fits(grant));assert_eq!(freed,step.progress().released_bytes);released+=freed;}assert!(copy.terminal_is_empty());let(_,allocated,freed)=crate::test_allocation::observe_backing(||drop(copy));assert_eq!((allocated,freed),(0,0));println!("[DEBUG] settlement partialcopy exactpaidrelease={released} copyseed={copy_bytes} onebelowretainsoriginalphysicalowner");}}
#[test]
fn edit_message_clamp_settlement_cancels_at_every_owned_stage(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();for bytes in [1,7]{for stage in law["settlement"]["cancelStages"].as_array().unwrap(){let baseline=serde_json::json!({"artifact":"unchanged","alternatives":["original"]});let mut messages=ReplayMessageAccumulator::default();let mut outcomes=Vec::new();for index in 0..6{let mut message=MutationMessage::fatal("mutation.invariant","x".repeat(1000));message.op_index=Some(index);let mut drain=crate::os_spr::command::OperationMessageDrain::new(MutationReplayOutcome {mutation_id:crate::os_spr::MutationId(format!("mutation:{index}")),edit_id:"owned-stages".into(),op_index:index,worst:Some(message.level),messages:vec![message],superseded:false,withdrawn:false});while !drain.is_finished(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:drain.next_copy_byte_demand(&messages),maximum_capacity_bytes:drain.next_capacity_byte_demand(&messages).unwrap(),maximum_release_bytes:drain.next_release_byte_demand(),maximum_depth:1};drain.step(&mut messages,grant).unwrap();}outcomes.push(drain.take().unwrap());}let original_status:Vec<_>=outcomes.iter().map(|outcome|outcome.worst).collect();let mut cursor=EditMessageSettlement::new("owned-stages",&messages,0,outcomes.len());for turn in 0..1_000_000{let reached=match stage.as_str().unwrap(){"clamp"=>turn==1,"outcome-retirement"=>matches!(cursor.phase,Phase::Reserve)&&cursor.messages.is_some(),"partial-copy"=>matches!(cursor.phase,Phase::Copy)&&cursor.copy.is_some(),"finished"=>cursor.is_finished(),_=>unreachable!()};if reached{if stage=="partial-copy"{for _ in 0..10{let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_copy_byte_demand(&messages).unwrap().max(bytes),maximum_capacity_bytes:cursor.next_capacity_byte_demand().unwrap(),maximum_release_bytes:cursor.next_release_byte_demand(&messages).unwrap(),maximum_depth:64};cursor.step(&mut messages,&mut outcomes,grant).unwrap();}assert!(cursor.copy.is_some());assert!(matches!(cursor.phase,Phase::Copy));assert!(outcomes[cursor.outcome].messages.is_empty());}break;}let before=cursor.completed_work();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.next_copy_byte_demand(&messages).unwrap().max(bytes),maximum_capacity_bytes:cursor.next_capacity_byte_demand().unwrap(),maximum_release_bytes:cursor.next_release_byte_demand(&messages).unwrap(),maximum_depth:64};cursor.step(&mut messages,&mut outcomes,grant).unwrap();assert_eq!(cursor.completed_work()-before,1);assert_eq!(outcomes.iter().map(|outcome|outcome.worst).collect::<Vec<_>>(),original_status);assert!(turn<999999,"requestedsettlementstagewasnotreached");}close(&mut cursor);assert!(cursor.terminal_is_empty());drop(cursor);while !messages.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:messages.next_close_copy_byte_demand(),maximum_capacity_bytes:0,maximum_release_bytes:messages.next_close_release_byte_demand().unwrap(),maximum_depth:1};messages.close_step(grant).unwrap();}for outcome in outcomes{let mut retirement=MutationMessageLedgerRetirement::from_replay_outcome(outcome);while !retirement.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:retirement.next_copy_byte_demand(),maximum_capacity_bytes:0,maximum_release_bytes:retirement.next_release_byte_demand().unwrap(),maximum_depth:retirement.next_depth_demand().unwrap()};retirement.close_step(grant).unwrap();}}assert_eq!(baseline,serde_json::json!({"artifact":"unchanged","alternatives":["original"]}));}}eprintln!("[DEBUG] edit settlement cancellation retains originalclamp/reservation/partialcopy/finished owners and fullfatalstatuses under1/7bodyseeds, separatephysicalreleases");}
